// Add a comment to a newly created article and verify that it is saved.
// Precondition (publishedArticle fixture): logged in, a new article is created, so it starts with no comments.
// 1. Post a comment with randomized text generated by Faker.
// 2. Verify the comment appears with the exact text, the author's avatar and name, and today's date.
// 3. Verify the comment input is cleared after posting.
// 4. Open My Articles in the profile and open the article again.
// 5. Verify the article has exactly one comment with the same text, author, and date.

import { test, expect } from '../fixtures';
import { faker } from '@faker-js/faker';

test('Add comment to article and verify it is saved', async ({
  publishedArticle,
  profilePage,
  articleDetailsPage,
}) => {
  const username = 'Emily Parker';
  const commentText = faker.lorem.sentence();

  // Today's date in the site format, e.g. "November 11, 2026"
  const today = new Date().toLocaleDateString('en-US', {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  });

  // The new article has no comments yet
  await expect(articleDetailsPage.comments).toHaveCount(0);

  // Post a comment
  await articleDetailsPage.addComment(commentText);

  // Verify the comment is displayed with the exact text, author's avatar and name, and today's date
  const comment = articleDetailsPage.getComment(commentText);
  await expect(comment.text).toHaveText(commentText);
  await expect(comment.avatar).toHaveAccessibleName(username);
  await expect(comment.author).toHaveText(username);
  await expect(comment.date).toHaveText(today);

  // Verify the comment input is cleared after posting
  await expect(articleDetailsPage.commentInput).toHaveValue('');

  // Go to profile and open the article from My Articles
  await profilePage.open(username);
  await profilePage.myArticlesTab.click();
  const articlePreview = await profilePage.findArticlePreview(publishedArticle.title);
  await articlePreview.title.click();
  await expect(articleDetailsPage.title).toHaveText(publishedArticle.title);

  // Verify the comment is saved: exactly one comment with the same text, author, and date
  await expect(articleDetailsPage.comments).toHaveCount(1);
  await expect(comment.text).toHaveText(commentText);
  await expect(comment.avatar).toHaveAccessibleName(username);
  await expect(comment.author).toHaveText(username);
  await expect(comment.date).toHaveText(today);
});
